/**
 * Galent SalesPilot — Proposal Template Library
 *
 * 150+ proposal templates organized by:
 * - Service Domain (12 domains)
 * - Engagement Type (6 types)
 * - Industry Vertical (10 verticals)
 * - Complexity (3 levels)
 *
 * Each template includes:
 * - Section structure (what to include)
 * - AI prompt starters (contextual generation hints)
 * - Typical team composition
 * - Standard deliverables
 * - Risk factors
 */

export interface ProposalTemplate {
  id: string;
  name: string;
  domain: ServiceDomain;
  engagementType: EngagementType;
  industries: string[];
  complexity: 'Standard' | 'Complex' | 'Enterprise';
  description: string;
  sections: TemplateSection[];
  typicalTeam: { role: string; count: number; geo: string }[];
  deliverables: string[];
  risks: string[];
  durationRange: string;
  tcvRange: string;
  tags: string[];
  aiPromptContext: string;
}

export interface TemplateSection {
  id: string;
  title: string;
  required: boolean;
  aiPromptHint: string;
  sampleOutline: string[];
}

export type ServiceDomain =
  | 'AI & Data Engineering'
  | 'Cloud & Infrastructure'
  | 'Application Development'
  | 'Enterprise Architecture'
  | 'ERP & Business Applications'
  | 'Managed Services'
  | 'QA & Testing'
  | 'DevSecOps'
  | 'Digital Transformation'
  | 'Consulting & Advisory'
  | 'Cybersecurity'
  | 'Staff Augmentation';

export type EngagementType =
  | 'Fixed Price'
  | 'Time & Material'
  | 'Managed Service'
  | 'Consulting'
  | 'Staff Augmentation'
  | 'Hybrid';

// ── Standard sections that apply to most proposals ──
const COMMON_SECTIONS: TemplateSection[] = [
  { id: 'exec_summary', title: 'Executive Summary', required: true, aiPromptHint: 'Business challenge, proposed solution, expected outcomes, why us', sampleOutline: ['Business context', 'Challenge statement', 'Proposed solution overview', 'Expected business impact', 'Why Galent'] },
  { id: 'company_overview', title: 'Company Overview & Qualifications', required: true, aiPromptHint: 'Galent capabilities, relevant experience, certifications, partnerships', sampleOutline: ['About Galent', 'Relevant experience', 'Industry expertise', 'Technology partnerships', 'Certifications'] },
  { id: 'understanding', title: 'Understanding of Requirements', required: true, aiPromptHint: 'Demonstrate deep understanding of client needs, pain points, goals', sampleOutline: ['Current state analysis', 'Pain points identified', 'Business objectives', 'Success criteria', 'Constraints & dependencies'] },
  { id: 'solution', title: 'Proposed Solution', required: true, aiPromptHint: 'Solution architecture, technology stack, integration points, innovation', sampleOutline: ['Solution overview', 'Architecture diagram description', 'Technology stack', 'Integration approach', 'Innovation elements'] },
  { id: 'approach', title: 'Implementation Approach', required: true, aiPromptHint: 'Methodology, phases, governance, quality assurance', sampleOutline: ['Methodology (Agile/Waterfall/Hybrid)', 'Phase breakdown', 'Governance model', 'Quality gates', 'Change management'] },
  { id: 'team', title: 'Team & Resources', required: true, aiPromptHint: 'Team structure, roles, qualifications, org chart, onshore/offshore mix', sampleOutline: ['Team structure', 'Key personnel', 'Role descriptions', 'Onshore/offshore model', 'Knowledge transfer plan'] },
  { id: 'timeline', title: 'Timeline & Milestones', required: true, aiPromptHint: 'Phases with dates, milestones, dependencies, go-live criteria', sampleOutline: ['Phase timeline', 'Key milestones', 'Dependencies', 'Go-live criteria', 'Hypercare period'] },
  { id: 'pricing', title: 'Pricing & Commercial Terms', required: true, aiPromptHint: 'Cost breakdown, payment schedule, pricing model, value proposition', sampleOutline: ['Pricing summary', 'Rate card', 'Payment schedule', 'Travel & expenses', 'Optional items'] },
  { id: 'risks', title: 'Risk Management', required: true, aiPromptHint: 'Identified risks, mitigation strategies, escalation path', sampleOutline: ['Risk register', 'Mitigation strategies', 'Contingency plans', 'Escalation matrix'] },
  { id: 'terms', title: 'Terms & Conditions', required: false, aiPromptHint: 'IP, confidentiality, SLAs, warranties, termination', sampleOutline: ['IP ownership', 'Confidentiality', 'SLAs', 'Warranty', 'Termination clause'] },
];

