// ── Template Generator ──

function makeTemplate(
  id: string, name: string, domain: ServiceDomain, engType: EngagementType,
  industries: string[], complexity: 'Standard' | 'Complex' | 'Enterprise',
  description: string, extraSections: TemplateSection[],
  team: { role: string; count: number; geo: string }[],
  deliverables: string[], risks: string[],
  durationRange: string, tcvRange: string, tags: string[], aiContext: string
): ProposalTemplate {
  return {
    id, name, domain, engagementType: engType, industries, complexity, description,
    sections: [...COMMON_SECTIONS, ...extraSections],
    typicalTeam: team, deliverables, risks, durationRange, tcvRange, tags,
    aiPromptContext: aiContext,
  };
}

