export const COMPLEXITY_LEVELS = ['Standard', 'Complex', 'Enterprise'] as const;

export function getTemplatesByDomain(domain: ServiceDomain): ProposalTemplate[] {
  return PROPOSAL_TEMPLATES.filter(t => t.domain === domain);
}

export function getTemplatesByIndustry(industry: string): ProposalTemplate[] {
  return PROPOSAL_TEMPLATES.filter(t => t.industries.includes(industry) || t.industries.includes('All'));
}

export function searchTemplates(query: string): ProposalTemplate[] {
  const q = query.toLowerCase();
  return PROPOSAL_TEMPLATES.filter(t =>
    t.name.toLowerCase().includes(q) ||
    t.description.toLowerCase().includes(q) ||
    t.tags.some(tag => tag.toLowerCase().includes(q)) ||
    t.domain.toLowerCase().includes(q)
  );
}

export function getTemplateById(id: string): ProposalTemplate | undefined {
  return PROPOSAL_TEMPLATES.find(t => t.id === id);
}
